+// API keys and role-based permissions.
+import { AppError } from "../errors.js";
+
+/** Permissions granted to each role. */
+export const ROLE_PERMISSIONS = Object.freeze({
+  viewer: Object.freeze(["read"]),
+  cook: Object.freeze(["read", "cook", "waste", "temperature", "stocktake_count"]),
+  manager: Object.freeze(["read", "cook", "waste", "temperature", "stocktake_count", "manage"]),
+});
+
+/** Finds the API key record for `key`, or throws AppError unauthorized. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || !key) throw new AppError("unauthorized");
+  const found = (store.data.apiKeys ?? []).find((k) => k.key === key);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Checks that `apiKey`'s role grants `permission`, or throws AppError forbidden. */
+export function authorize(apiKey, permission) {
+  const allowed = ROLE_PERMISSIONS[apiKey?.role];
+  if (!allowed || !allowed.includes(permission)) throw new AppError("forbidden");
+}
