+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { t } from "../src/i18n/messages.js";
+import { app, authHeaders, fresh, NOW, seed } from "./helpers.js";
+
+const viewer = authHeaders("viewer");
+const cook = authHeaders("cook");
+const manager = authHeaders("manager");
+
+test("missing or unknown API key returns 401 in the error shape", async () => {
+  const { handle } = app();
+  const missing = await handle({ path: "/items" });
+  assert.equal(missing.status, 401);
+  assert.equal(missing.body.error.code, "unauthorized");
+  assert.ok(missing.body.error.message.length > 0);
+
+  const wrong = await handle({ path: "/items", headers: { Authorization: "Bearer nope" } });
+  assert.equal(wrong.status, 401);
+  assert.equal(wrong.body.error.code, "unauthorized");
+
+  const malformed = await handle({ path: "/items", headers: { Authorization: "Basic abc" } });
+  assert.equal(malformed.status, 401);
+  assert.equal(malformed.body.error.code, "unauthorized");
+
+  assert.notEqual(t("unauthorized", "ko"), "unauthorized");
+  assert.notEqual(t("forbidden", "ko"), "forbidden");
+});
+
+test("viewer can read GET routes but cannot write or read /audit", async () => {
+  const { handle } = app();
+  assert.equal((await handle({ path: "/items", headers: viewer })).status, 200);
+  assert.equal((await handle({ path: "/batches", headers: { Authorization: viewer.authorization } })).status, 200);
+  assert.equal((await handle({ path: "/alerts", headers: viewer })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/recipes/1/cook", body: { portions: 4 } },
+    { method: "POST", path: "/batches/1/waste", body: { qty: 1 } },
+    { method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: viewer });
+    assert.equal(res.status, 403, `${req.method} ${req.path} should be 403 for viewer`);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("cook can read, cook, record waste, log temperatures and enter stock-take counts", async () => {
+  const { handle } = app();
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } })).body;
+
+  assert.equal((await handle({ path: "/items", headers: cook })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 4 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/6/waste", headers: cook, body: { qty: 0.5, reason: "spill" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 4 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, headers: cook, body: { batchId: 6, counted: 12 } })).status, 200);
+
+  for (const req of [
+    { method: "POST", path: "/stocktakes", body: { location: "fridge" } },
+    { method: "POST", path: `/stocktakes/${take.id}/finish` },
+    { method: "POST", path: "/orders", body: { supplierId: 1, lines: [{ itemId: 1, qty: 2 }] } },
+    { method: "POST", path: "/orders/3/send" },
+    { method: "POST", path: "/orders/3/cancel" },
+    { method: "POST", path: "/prices", body: { supplierId: 1, itemId: 1, priceCents: 190, validFrom: "2026-11-01" } },
+    { method: "POST", path: "/dishes", body: { name: "Soup", recipeId: 1, priceCents: 900 } },
+    { method: "PUT", path: "/items/1/allergens", body: { allergens: [] } },
+    { method: "POST", path: "/jobs/nightly" },
+    { method: "GET", path: "/audit" },
+  ]) {
+    const res = await handle({ ...req, headers: cook });
+    assert.equal(res.status, 403, `${req.method} ${req.path} should be 403 for cook`);
+    assert.equal(res.body.error.code, "forbidden");
+  }
+});
+
+test("data-changing requests write audit entries listed newest first for managers", async () => {
+  const store = fresh();
+  let tick = NOW;
+  const handle = createApp(store, { clock: () => tick });
+
+  await handle({ path: "/items", headers: viewer });
+  await handle({ method: "POST", path: "/orders", headers: viewer, body: { supplierId: 1, lines: [{ itemId: 1, qty: 1 }] } });
+
+  await handle({ method: "POST", path: "/recipes/1/cook", headers: cook, body: { portions: 4 } });
+  tick += 60_000;
+  await handle({ method: "POST", path: "/temperatures", headers: cook, body: { location: "fridge", celsius: 3 } });
+  await handle({ method: "POST", path: "/stocktakes", headers: manager, body: { location: "dry" } });
+
+  const audit = await handle({ path: "/audit", headers: manager });
+  assert.equal(audit.status, 200);
+  assert.equal(audit.body.length, 3);
+  assert.deepEqual(
+    audit.body.map(({ at, keyName, method, path, status }) => ({ at, keyName, method, path, status })),
+    [
+      { at: new Date(NOW + 60_000).toISOString(), keyName: "manager", method: "POST", path: "/stocktakes", status: 201 },
+      { at: new Date(NOW + 60_000).toISOString(), keyName: "cook", method: "POST", path: "/temperatures", status: 201 },
+      { at: new Date(NOW).toISOString(), keyName: "cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.equal(seed().apiKeys.length, 3);
+});
